Original:
```typescript
export function refundAmount(paidCents: number, opened: boolean): number {
  if (!opened) {
    return paidCents;
  }
  if (paidCents < 0) {
    throw new RangeError(`paid cannot be negative, got ${paidCents}`);
  }
  const fee = Math.round((paidCents * RESTOCKING_PERCENT) / 100);
  return paidCents - fee;
}

```

